"""Render scoped claims without pooling campaigns or inventing attribution."""
from common import *
from compare import choices

def table(report):
 lines=['| 조건 | 비교 | mean paired gain | bootstrap 95% CI | faster | wall 감소 |','|---|---|---:|---|---:|---:|']
 for c in report['cells']:
  for label,v in c['contrasts'].items():
   lo,hi=v['bootstrap_95_pct'];lines.append(f"| {c['condition']} | {label} | {v['mean_paired_gain_pct']:+.3f}% | [{lo:+.3f}, {hi:+.3f}]% | {v['faster_blocks']}/8 | {v['mean_paired_wall_reduction_pct']:+.3f}% |")
 return lines

def write_reports(new,comparison,counts,proof):
 verdict=comparison['campaign_verdicts']['replication_component']
 lines=['# 새 구성 요소 재현 캠페인','',f"새 캠페인 상태: **{new['status']}**. 기존 기여 분석과 별개인 새 실행 정확히 1회입니다. 동일 AMD 장비에서 시간적으로 분리했으며 외부 팀/장비 재현이나 새로운 workload 일반화가 아닙니다.",'','A(E-R), model, runtime/DSO, E sensor/threshold/margin/guards, observe BPF object를 변경하지 않았습니다. persistent pool off. 원본과 cases/fixtures/order/identity는 동일하며 harness 변경은 출력 격리·현재 실행 연결·누락 검출 강화뿐입니다. patch와 protocol-diff.json을 함께 보존했습니다.','']+table(new)
 lines+=['','## 새 캠페인 절대 성능','','| 조건 | arm | tokens/s 평균 | cohort wall s 평균 | server CPU s 평균 |','|---|---|---:|---:|---:|']
 for c in new['cells']:
  for arm,m in c.get('absolute',{}).items():lines.append(f"| {c['condition']} | {arm} | {m['tokens_per_second']:.4f} | {m['wall_s']:.4f} | {m['cpu_s']:.4f} |")
 lines+=['','## 독립 구성 요소 판정','',f"새 실행 판정: `{json.dumps({k:v for k,v in verdict.items() if k!='conditions'},ensure_ascii=False)}`."]
 for cond,details in verdict.get('conditions',{}).items():
  lines += [f"- {cond}: E의 실제 eligible multi-token worker 선택이 다른 block={details['E_different_choice_blocks']}; A_S와 A_L의 선택이 다른 block={details['S_E_mediated_blocks']}."]
 lines+=['','F6_L은 압력 센서와 shadow choice, 유효성/연속성 검사, semantic phase 전달을 유지하고 적격 multi-token Decode만6으로 고정합니다. single-token5 예외와 UNKNOWN/MIXED fallback은 기존 소스 그대로입니다. 이 fixture에서 모든 fallback을 별도 유발했다는 뜻은 아닙니다.','', 'E의 CPU25 판정은 A_L/F6_L CI lower>0와 실제 선택 차이에 근거합니다. 별도5% 기준을 추가하지 않았습니다. ambient에서 두 설정의 선택이 같으면 작은 시간 차이를 선택 효과로 주장하지 않습니다. E에는 semantic phase가 쓰이지만, 이 ablation은 semantic label 자체의 다른 controller 대비 고유 가치를 분리하지 않습니다.','', 'observe/FULL/partial/fixed-affinity S는 phase를 기록하지만 phase-dependent placement를 하지 않습니다. A_S/A_L은 동일 userspace 정책에 S를 추가한 효과이며 실제 E 선택이 달라지면 매개 효과도 포함합니다. CI가0을 포함하면 inconclusive이며 효과0, 동등성, 무오버헤드가 입증된 것이 아닙니다. fixed6_S 또는 fixed5 arm이 없어 완전한 interaction 분해나 모든 static 정책 대비 우월성을 주장하지 않습니다.','', '실제 SCHED_EXT server/worker, Linux loader/launcher/load, ops/BPF tags, marker ELF/PID, phase bits, FULL mask/tracking/drop/export errors, handoff moved=0, no bypass/detach/fallback 및 정상 cleanup을 검사했습니다. old dynamic-affinity 실패는 여전히 미해결입니다. OpenMP 로그의 관측된 team 크기 집합을 모든 graph의 연속 관측으로 해석하지 않습니다.','','## 호출 수·정확성·재계산','',f"실제 호출 집계: `{json.dumps(counts,ensure_ascii=False)}`.",'', '하나의 atomic prompt-array /completion에 distinct request8개, 각128 generated tokens입니다. 독립 HTTP client8개 workload가 아닙니다. 각 fresh server의 동일 warmup1회는 제외하고 측정1회만 primary에 사용했습니다. 모든 유효 warmup/측정 출력은 frozen B0 oracle과 직접 비교했으며 teacher forcing은 사용하지 않았습니다. 기존 R logits checkpoint와 이번 token equality의 범위는 다릅니다. 새 전체 logits 검사는0회입니다.','', 'Primary는 실제 generated tokens / 전체 cohort HTTP wall seconds입니다. queueing·prefill·decode·정책 비용·응답 read/JSON parse를 포함하고 loading과 warmup을 제외합니다. 8개 요청이나1024 tokens가 아니라8 paired blocks가 반복 단위입니다. cohort별4 blocks, 동일 가중치,10,000 stratified resamples(seed20261122), 기존 선형 percentile을 유지했습니다. 다섯 contrast는 같은 complete-block resample을 공유합니다.','',f"강화된 모델 없는 재계산: {proof['status']}. 원본 코드와 정상 자료의 출력 dictionary가 정확히 같음을 확인했고, 임시 복사본에서 한 방문을 누락시키면 nonzero INCOMPLETE_INVALID가 됨을 확인했습니다. 원본 코드는 수정하지 않았습니다.",'', 'CPU25는 CPU10의 .0125 process CPU seconds/.05 seconds 고정 간섭, 약0.25 core입니다. 머신 전체25% 또는 cgroup quota25%가 아닙니다. measured .22-.28 core, affinity와 Linux policy를 실제 counter로 검증했습니다. CPU seconds는 에너지가 아니며 nonstream TTFT/p95 token latency는 측정하지 않았습니다.','', '기본 성능 실행의 역할은 A_L, A_S는 scoped integration/evaluation입니다. runtime 경로나 기본 symlink를 교체하지 않았습니다. 이번 goal 후 추가 기능 연구나 세 번째 기여 캠페인을 자동 실행하지 않습니다. 현재 지원 범위의 제출용 연구 기준점이며 production-ready 선언이 아닙니다.']
 (D/'replication-summary.md').write_text('\n'.join(lines)+'\n')
 lines=['# 캠페인별 최종 근거 비교','',f"상태: `{json.dumps(comparison['states'],ensure_ascii=False)}`.",'','기여 분석 원본1회와 새 재현1회를 각각 판정합니다. 이전 A/B0 두 캠페인에는 F6/S가 없으므로 E/S 재현 횟수에 포함하지 않습니다. 어느 결과도 합쳐 하나의 좋은 CI로 대체하지 않습니다.','', '| 기여 캠페인 | 전체 조합 | E CPU25 | E ambient | S CPU25 | S ambient |','|---|---|---|---|---|---|']
 for name,v in comparison['campaign_verdicts'].items():lines.append('| '+name+' | '+' | '.join(v[k] for k in ['overall_system','E_cpu25','E_ambient','S_cpu25','S_ambient'])+' |')
 for name,row in comparison['rows'].items():lines+=['',f'## {name}','']+table(row)
 lines+=['','## 모든 캠페인의 절대 성능','','| 캠페인 | 조건 | arm | mean tokens/s | mean wall s | mean server CPU s |','|---|---|---|---:|---:|---:|']
 for earlier in comparison['prior_A_B0_reference']:
  for c in earlier['cells']:
   for arm,m in c['absolute'].items():lines.append(f"| earlier_A_B0_{earlier['campaign']} (참고) | {c['condition']} | {arm} | {m['tokens_per_second']:.4f} | {m['wall_s']:.4f} | {m['cpu_s']:.4f} |")
 for name,row in comparison['rows'].items():
  for c in row['cells']:
   for arm,m in c.get('absolute',{}).items():lines.append(f"| {name} | {c['condition']} | {arm} | {m['tokens_per_second']:.4f} | {m['wall_s']:.4f} | {m['cpu_s']:.4f} |")
 lines+=['','이전 runtime-only A/B0 paired gain/CI (E/S 근거 아님):','']
 for earlier in comparison['prior_A_B0_reference']:
  for c in earlier['cells']:lines.append(f"- earlier_A_B0_{earlier['campaign']} {c['condition']}: {c['mean_paired_gain_pct']:+.4f}%, CI {c['paired_stratified_bootstrap_95_pct']}, faster {c['faster_pairs']}/8.")
 lines+=['','## baseline 변동 해석','', '이전 A/B0 CPU25 B0는 약41.08/40.99 t/s, A는51.75/51.71이었고, 원본 기여 분석에서는 B0 약38.68, A 약51.03이었습니다. 따라서 상대개선이 약26%에서32.39%로 커진 것을 새 코드가 더 빨라진 증거로 해석하지 않습니다. 이번에도 runtime 변경은0입니다.','',f"원본 기여 분석 대비 새 캠페인의 절대 평균 t/s 변화(캠페인 간 descriptive ratio이며 primary paired gain 아님): `{json.dumps(comparison['between_component_campaign_absolute_mean_change_pct'])}`.",'', '변동 원인: **CAUSE_UNDETERMINED**. 온도/주파수/전원/load snapshots는 관측값이며 원인 분리 실험이 아닙니다. 느린 유효 B0 block도 모두 유지했습니다. 결과를32%에 맞추는 power/affinity/load 조정을 하지 않았습니다.','', '원본 CPU25 E/fixed6의8 pair는 모두 양수였고 범위는 약+6.705~+16.083%였습니다. 이 범위를 새 합격 임계값으로 쓰지 않습니다. 각 캠페인의 실제 pair 범위·cohort별·순서별 결과는 아래와 JSON에 별도로 제시합니다.','','## cohort와 실행 순서별 결과','','각 순서 그룹은 descriptive summary이며 추가 독립 표본이나 새 gate가 아닙니다.','']
 for name,row in comparison['rows'].items():
  lines += [f'### {name}','','| 조건 | 비교 | h1 / h2 mean gain | 전체 pair 범위 | 순서별 mean gain (n) |','|---|---|---|---|---|']
  for cond,contrasts in row['grouped'].items():
   for label,g in contrasts.items():
    co=g['by_cohort'];orders='; '.join(f"{k}: {v['mean_paired_gain_pct']:+.3f}% (n={v['n']})" for k,v in g['by_order'].items());lo,hi=g['pair_gain_range_pct'];lines.append(f"| {cond} | {label} | {co['heldout-1']:+.3f}% / {co['heldout-2']:+.3f}% | [{lo:+.3f}, {hi:+.3f}]% | {orders} |")
 lines+=['','## 환경 brackets','','주파수는 각 pre/post snapshot의 선택된6 CPU 평균값 범위입니다. 연속 frequency trace가 아닙니다. 전원·governor·boost 원문과 raw 경로는 JSON에 있습니다.','','| 캠페인 | 조건/arm | CPU °C 범위 | selected mean GHz 범위 | loadavg1 범위 | 실제 generator core 범위 |','|---|---|---|---|---|---|']
 env=dict(comparison['environment'])
 for v in comparison['prior_A_B0_reference']:env['earlier_A_B0_'+str(v['campaign'])]=v['environment']
 for name,groups in env.items():
  for key,v in groups.items():lines.append(f"| {name} | {key} | {v['CPU_temperature_c_range']} | {v['selected_frequency_mean_GHz_range']} | {v['loadavg1_range']} | {v['actual_generator_cores_range']} |")
 lines+=['','최종 역할: A_L은 기본 성능 실행, A_S는 보존된 observe를 포함한 연구 평가 구성입니다. 지원 범위는 같은 AMD·모델·historical cohorts·고정 ambient/0.25-core 간섭 조건입니다. 외부 장비/Intel, 모든 길이/모델/정적 정책, 변동 부하, 일반 품질 및 production readiness는 미검증입니다. 제출용 기준점을 동결하며 추가 캠페인은 이 goal에서 실행하지 않습니다.']
 (D/'campaign-comparison.md').write_text('\n'.join(lines)+'\n')
 matrix=['# Claim-evidence matrix','', '| 주장 | 현재 증거 | 범위 | 미검증/제한 |','|---|---|---|---|',f"| 전체 A_S/B0 효과 재현 | campaign-comparison.json states.overall_system={comparison['states']['overall_system']}; 캠페인별2조건 gate | 원본+새 기여 실행2회, 같은 장비 | 외부 재현·새 workload 일반화 아님 |",f"| E의 fixed6 대비 CPU25 선택 효과 | {comparison['states']['E_cpu25']}; 각 캠페인 CI와 실제 선택 차이 | 센서/guard를 유지한 eligible multi-token Decode 선택 | fixed5 또는 모든 static 정책 우월성 아님 |",'| E ambient | 각 캠페인 E_ambient와 실제 선택 count | 동일 선택이면 미소 시간차를 적응 이득으로 주장하지 않음 | 효과0/동등성 증명 아님 |','| S 추가 효과 | 캠페인·조건별 A_S/A_L sign/CI; 실제 kernel admission | 동일 userspace에 observe/FULL 추가 | inconclusive는 무오버헤드 증명이 아님; fixed6_S 없음 |','| semantic phase 활용 | sources/newa-prefill-pressure.h, frozen runtime identity, raw epochs | E가 phase를 사용하고 A/F6 모두 전달 유지 | label 자체의 다른 controller 대비 고유 가치 미분리 |','| phase-dependent kernel placement | sources/handoff.bpf.c, compile.log, moved=0 | observe는 관측만 함 | 새로운 phase-aware dispatch 개선을 입증하지 않음 |','| 출력 호환 | 모든 새 warmup/측정 raw tokens vs frozen B0 oracle; 기존 R checkpoint 별도 | declared fixtures의 자유 생성 | 새 logits 전수검사0, 일반 품질 증명 아님 |','| 실제 CPU/DSO/model 적용 | runtime.json, worker snapshots, loaded alias inode/hash, model hash, scheduler evidence | 고정6 CPU envelope, 해당 kernel/BTF | dynamic-affinity 역사적 실패 미해결 |','| 부담 동일성 | CPU10 .0125/.05 generator 실제 counters .22-.28 core | 고정0.25-core 간섭 | 전체CPU25%/quota25% 아님 |','| 원본 보존 | protected-before/after; original ZIP SHA; harness-isolation proof | 기존 workspace 전체 content/mode | 기존 원본 결과를 새 판정으로 덮어쓰지 않음 |','| 완결성 재계산 | 64 visits/128 cohorts/10 contrasts 요구; 누락 negative test | 원시 수치 별도 구현, 모델 불필요 | 계측의 모든 잠재적 오류나 원인 분리 증명 아님 |','| 캠페인 간 baseline 변동 | 모든 arm 절대값·cohort/order/environment table | 관측된 변화 | CAUSE_UNDETERMINED; 사후 outlier 제거 없음 |','| 최종 실행 역할 | frozen-release-map.json, exact cases, reproduce.sh | A_L 기본, A_S 평가; 지원 범위 제출 기준점 | production-ready 아님; 자동 Git push/tag 변경 없음 |']
 (D/'claim-evidence-matrix.md').write_text('\n'.join(matrix)+'\n')
